6	#include <sys/param.h>
7	#include <sys/user.h>
8	#include <sys/proc.h>
9	#include <sys/vm.h>
10	#include <sys/systm.h>
11	#ifdef SWAPRAM
12	#include <machine/swapram.h>
13	#endif
14	
15	void
16	brk()
17	{
18	    struct a {
19	        int naddr;
20	    };
21	    register int newsize, d;
22	
23	    /* set newsize to new data size */
24	    newsize = ((struct a*)u.u_arg)->naddr - u.u_procp->p_daddr;
25	    if (newsize < 0)
26	        newsize = 0;
27	#ifdef SWAPRAM
28	    /*
29	     * A large process may grow to its ceiling; a small one cannot ask
30	     * for LARGE here, because its stack already sits under the window
31	     * and the bonus lies above that stack.
32	     */
33	    if (u.u_tsize + newsize + u.u_ssize > swapram_ceiling (u.u_procp)) {
34	#else
35	    if (u.u_tsize + newsize + u.u_ssize > MAXMEM) {
36	#endif
37	        u.u_error = ENOMEM;
38	        return;
39	    }
40	    /*
41	     * The stack has grown down to p_saddr and grows further as the
42	     * process runs; data that reaches it is data the stack will
43	     * overwrite. u_ssize alone does not see that: it is the stack's
44	     * size so far, not where it ends.
45	     */
46	    if (u.u_procp->p_daddr + newsize > u.u_procp->p_saddr) {
47	        u.u_error = ENOMEM;
48	        return;
49	    }
50	
51	    u.u_procp->p_dsize = newsize;
52	
53	    /* set d to (new - old) */
54	    d = newsize - u.u_dsize;
55	//printf ("brk: new size %u bytes, incremented by %d\n", newsize, d);
56	    if (d > 0)
57	        bzero ((void*) (u.u_procp->p_daddr + u.u_dsize), d);
58	    u.u_dsize = newsize;
59	    u.u_rval = u.u_procp->p_daddr + u.u_dsize;
60	}
61	

TARGETS (2 — return all 2, one entry per id):
- id=brk | function | lines L16-L16
- id=a | class | lines L18-L20
